import { ReferenceColumn, SlushBucketColumn } from '../../../../db'
import { ActionDefinition } from '../../../Action'
import type { FlowValueType } from '../../../FlowTypes'

export const getCatalogVariables = ActionDefinition({
    $id: '330ba3abc31013002841b63b12d3aee8',
    name: 'Get Catalog Variables',
    description: `<p>Surface Catalog Variables on the Flow and/or on a given record.</p>
    <p>Obtains the catalog variables in a Flow or from a record in a table.
    Uses an existing catalog item as a template to populate the available variables.</p>`,
    category: 'bf2f2fec73f70300b61e66476bf6a774',
    inputs: {
        catalog_variables: SlushBucketColumn({
            label: 'Catalog Variables',
            maxLength: 12000,
        }),
        requested_item: ReferenceColumn({
            label: 'Submitted Request',
            mandatory: true,
            referenceTable: 'sc_req_item',
        }),
        template_catalog_item: ReferenceColumn({
            label: 'Template Catalog Items and Variable Sets',
            mandatory: true,
            referenceTable: 'st_sys_catalog_items_and_variable_sets',
        }),
    },
    outputs: {} as Record<string, FlowValueType>,
})
